export const getNewDate = (rank, maxRepetitionDays) => {
    const today = dayjs()
    let newDay;

    if (rank === 0 || rank === null) {
        newDay = today.add(1, 'day')
    } else if (rank === 1) {
        newDay = today.add(1, 'day')
    } else if (rank === 2) {
        newDay = today.add(2, 'day')
    } else if (rank === 3) {
        newDay = today.add(3, 'day')
    } else if (rank === 4) {
        newDay = today.add(7, 'day')
    } else if (rank === 5) {
        newDay = today.add(14, 'day')
    } else if (rank === 6) {
        newDay = today.add(21, 'day')
    } else if (rank === 7) {
        newDay = today.add(30, 'day')
    } else if (rank === 8) {
        newDay = today.add(45, 'day')
    } else if (rank === 9) {
        newDay = today.add(60, 'day')
    } else if (rank === 10) {
        newDay = today.add(maxRepetitionDays, 'day')
    }
    return newDay.format('YYYY-MM-DD').toString()
}

export const increaseRank = (rank, isFirstRound = false) => {
    // console.log('isFirstRound', isFirstRound)
    if(isFirstRound) {
        rank = rank + 1
    }
    
    if (rank >= 10)
        return 10
    return rank
}

export const decreaseRank = (rank) => {
    rank = rank - 1
    if (rank <= 0)
        return 0
    return rank
}

export const getColouredTitleCard = (title) => {
    const prefix = title.substring(0, 4)
    title = title.replace(/ /g, '\u00A0')
    if (prefix === 'der ') {
        return <span className="text-green-500">{title}</span>
    } else if (prefix === 'die ') {
        return <span className="text-pink-500">{title}</span>
    } else if (prefix === 'das ') {
        return <span className="text-orange-500">{title}</span>
    }
    return <span>{title}</span>
}

export const replaceSpecialCharacters = (word) => {
    return word
        .toLowerCase()
        .replaceAll("ñ", "n")  // hiszpański
        .replaceAll('ß', 'ss')  // niemiecki
        .normalize("NFD")
        .replaceAll(/[\u0300-\u036f]/g, "");
}

export const removeDeArticles = (word) => {
    return word
        .replaceAll("der ", "")
        .replaceAll('die ', '')
        .replaceAll('das ', '')
}

export const removeItArticles = (word) => {
    return word
        .replaceAll("il ", "")
        .replaceAll("lo ", "")
        .replaceAll('la ', '')
        .replaceAll('le ', '')
        .replaceAll('i ', '')
        .replaceAll('gli ', '')
}

export const removeEsArticles = (word) => {
    return word
        .replaceAll("el ", "")
        .replaceAll('la ', '')
        .replaceAll('los ', '')
        .replaceAll('las ', '')
}

export const compareWords = (guess, word, hint, checkArticle) => {
    if (guess === '') {
        return false
    }
    guess = replaceSpecialCharacters(guess)
    word = replaceSpecialCharacters(word)

    let words = []
    if (hint) {
        words = hint.split(",").map(word => replaceSpecialCharacters(word.trim()));
    }
    // console.log('words 1: ', words)

    if (!checkArticle["de-DE"]) {
        word = removeDeArticles(word)
        guess = removeDeArticles(guess)
        if (words) {
            words = words.map(word => removeDeArticles(word.trim()));
        }
    }
    if (!checkArticle["it-IT"]) {
        word = removeItArticles(word)
        guess = removeItArticles(guess)
        if (words) {
            words = words.map(word => removeItArticles(word.trim()));
        }
    }
    if (!checkArticle["es-ES"]) {
        word = removeEsArticles(word)
        guess = removeEsArticles(guess)
        if (words) {
            words = words.map(word => removeEsArticles(word.trim()));
        }
    }
        
    words.push(word)
    // console.log('guess: ', guess)
    // console.log('word: ', word)
    // console.log('words: ', words)
    // console.log('result: ', words.includes(guess))

    return words.includes(guess)
}